/** 有限板子的警徽写入在实际同步提交时缓存，不在失败 checkpoint 中刷新。 */
export function openDemonBadgeFrame(world: World): Readonly<{
  commit: (
    change:
      | { kind: "assign"; sheriffId: number; weight: number; policy: string | undefined }
      | {
          kind: "handoff";
          fromId: number;
          toId: number | null;
          weight: number;
          policy: string | undefined;
        },
  ) => void;
}> | null {
  const b = bindings.get(world);
  if (!b) return null;
  if (!validBinding(b)) throw new Error("demon_hunter_badge_original_state_revoked");
  const before = new Map(
    [...b.players.values()].map((p) => {
      const cp = p.checkpoint;
      if (
        !cp ||
        world.getComponent(p.id, COMPONENT.Badge) !== cp.badge ||
        world.getComponent(p.id, COMPONENT.VotingRight) !== cp.vote ||
        !originalLife(p, world) ||
        demonBadgeJson(cp.badge) !== cp.badgeJson ||
        demonVoteJson(cp.vote) !== cp.voteJson ||
        !writableDemonFields(cp.badge, ["isSheriff", "destroyed", "voteWeight"]) ||
        !writableDemonFields(cp.vote, ["weight"]) ||
        !Object.isExtensible(cp.badge) ||
        Object.getOwnPropertyDescriptor(cp.badge, "handoffPolicy")?.configurable === false
      )
        throw new Error("demon_hunter_badge_stock_revoked");
      return [
        p.id,
        {
          cp,
          badge: JSON.parse(cp.badgeJson),
          vote: JSON.parse(cp.voteJson),
          alive: p.lifeDescriptor.get!.call(p.life) === true,
        },
      ] as const;
    }),
  );
  let committed = false;
  return Object.freeze({
    commit: (change) => {
      if (
        committed ||
        !validBinding(b) ||
        change.weight !== 1.5 ||
        change.policy !== (b.config.nobleSecretBody ? "awa_holder_choice_v1" : undefined)
      )
        throw new Error("demon_hunter_badge_commit_invalid");
      const expected = new Map(
        [...before].map(([id, item]) => [id, { badge: { ...item.badge }, vote: { ...item.vote } }]),
      );
      if (change.kind === "assign") {
        if (!before.get(change.sheriffId)?.alive)
          throw new Error("demon_hunter_badge_commit_invalid");
        for (const [id, item] of before)
          if (item.alive) {
            const next = expected.get(id)!;
            next.badge.isSheriff = id === change.sheriffId;
            next.badge.destroyed = false;
            next.badge.voteWeight = change.weight;
            if (change.policy) next.badge.handoffPolicy = change.policy;
            else delete next.badge.handoffPolicy;
            if (next.vote.canVote) next.vote.weight = id === change.sheriffId ? change.weight : 1;
          }
      } else {
        const from = expected.get(change.fromId);
        if (
          !from ||
          !from.badge.isSheriff ||
          from.badge.destroyed ||
          change.toId === change.fromId ||
          (change.toId !== null && !before.get(change.toId)?.alive)
        )
          throw new Error("demon_hunter_badge_commit_invalid");
        from.badge.isSheriff = false;
        from.badge.destroyed = true;
        from.vote.weight = from.vote.canVote ? 1 : 0;
        if (change.toId !== null) {
          const next = expected.get(change.toId)!;
          next.badge.isSheriff = true;
          next.badge.destroyed = false;
          next.badge.voteWeight = change.weight;
          if (change.policy) next.badge.handoffPolicy = change.policy;
          else delete next.badge.handoffPolicy;
          next.vote.weight = change.weight;
        }
      }
      for (const [id, next] of expected) {
        const cp = before.get(id)!.cp;
        if (
          world.getComponent(id, COMPONENT.Badge) !== cp.badge ||
          world.getComponent(id, COMPONENT.VotingRight) !== cp.vote ||
          demonBadgeJson(cp.badge) !== JSON.stringify(next.badge) ||
          demonVoteJson(cp.vote) !== JSON.stringify(next.vote)
        )
          throw new Error("demon_hunter_badge_commit_revoked");
      }
      committed = true;
      acceptDemonBadgeAudits(before, expected);
    },
  });
}

/** 原生警徽可选 metadata 必须区分缺失与被拒绝的 accessor。 */
export function assertDemonBadgeReadable(world: World): void {
  const b = bindings.get(world);
  if (!b) return;
  for (const p of b.players.values()) {
    const cp = p.checkpoint;
    if (!cp) continue;
    if (
      world.getComponent(p.id, COMPONENT.Badge) !== cp.badge ||
      world.getComponent(p.id, COMPONENT.VotingRight) !== cp.vote ||
      !demonBadgeJson(cp.badge) ||
      !demonVoteJson(cp.vote)
    )
      throw new Error("demon_hunter_badge_unreadable");
  }
}

export function demonNativeNightActor(
  world: World,
  kind: "seer_check" | "guard",
): { actorId: number; ability: object } | null {
  const b = bindings.get(world),
    n = b?.active;
  if (!b || !n || n.closed || n.frozen || !validBinding(b))
    throw new Error("demon_hunter_native_night_unavailable");
  const p = [...b.players.values()].find(
    (p) => p.kind === (kind === "seer_check" ? Role.Seer : Role.Guard),
  );
  if (!p || !n.targets.has(p.id) || demonRedMoonNightSealed(world, n.day)) return null;
  const ability = ownDemonData(ownDemonData(p.privateState, "abilities"), `native:${kind}`);
  if (!ability || typeof ability !== "object")
    throw new Error("demon_hunter_native_night_unavailable");
  return { actorId: p.id, ability };
}

/** 原生红月状态的有限审计转换，不采用任意 live 库存。 */
export function commitDemonRedMoonTransition(
  world: World,
  actorId: number,
  kind: "blast" | "exile" | "expire",
  day: number,
): boolean {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  const n = kind === "expire" ? b?.active : b?.nights.get(day);
  if (
    !b ||
    !p ||
    !n ||
    n.day !== day ||
    !validBinding(b) ||
    String(p.kind) !== RED_MOON_ROLE ||
    ![...b.players.values()].every((player) => originalLife(player, world)) ||
    !privateAuditCurrent(p, () => delegatedCurrent(b))
  )
    return false;
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || !writableDemonFields(state, ["blastDay", "exileDay", "expirySettled"]))
    return false;
  // 本族编码函数只消费已捕获的影子；解析查找先于 audit 字段读取，原体／夜权限仍留在这里。
  const original = readRedMoonShadow(() => p.auditPrivateJson);
  const next = copyRedMoonPayload(state);
  if (kind === "expire") {
    if (n.closed || !n.frozen || state.exileDay !== day - 1 || state.expirySettled) return false;
    next.expirySettled = true;
  } else {
    if (
      b.active ||
      !n.closed ||
      !n.frozen ||
      [...b.nights.keys()].some((d) => d > day) ||
      !originalLife(p, world, true) ||
      state.blastDay !== null ||
      state.exileDay !== null
    )
      return false;
    const wolves = [...b.players.values()].filter(
      (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
    ).length;
    if (kind === "blast") {
      if (wolves === 1 && state.lastWolfBlastPolicy === "forbidden") return false;
      next.blastDay = day;
    } else if (kind === "exile") {
      if (wolves !== 1) return false;
      next.exileDay = day;
    } else return false;
  }
  const expected = encodeRedMoonShadow(original, next);
  // 三写只归本族 slot；完整容器验收和 audit 最终更新保持原点，后续失败不撤销先前字段。
  writeRedMoonTransition(state, next);
  acceptDemonRedMoonAudit(p, expected);
  return true;
}

/** 原红月自爆只抑制紧接的下一夜好人行动。 */
export function demonRedMoonNightSealed(world: World, day: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = [...b.players.values()].find((p) => String(p.kind) === RED_MOON_ROLE);
  if (!p) return false;
  if (!validBinding(b) || ![...b.players.values()].every((p) => originalLife(p, world)))
    throw new Error("red_moon_original_state_revoked");
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || !privateAuditCurrent(p, () => delegatedCurrent(b))) throw new Error("red_moon_original_state_revoked");
  const sealed = Number.isSafeInteger(day) && day > 1 && state.blastDay === day - 1;
  if (sealed && originalLife(p, world, true)) throw new Error("red_moon_blast_death_unsettled");
  return sealed;
}

/** 有限板子的白痴翻牌时，同时保留私有库存与公开票权审计。 */
export function commitDemonIdiotReveal(world: World, actorId: number): boolean {
  const b = bindings.get(world);
  if (!b) return false;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(p, () => delegatedCurrent(b)) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson ||
    !writableDemonFields(p.privateState, ["idiot"]) ||
    !writableDemonFields(cp.vote, ["canVote", "weight"])
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const before = ownDemonData(p.privateState, "idiot");
  if (!exactDemonData(before, ["revealed"]) || ownDemonData(before, "revealed") !== false)
    throw new Error("demon_hunter_idiot_state_revoked");
  // 消耗翻牌前先验证后续同步警徽交接。
  openDemonBadgeFrame(world);
  return commitDemonIdiotParticipantData(p, cp);
}

/** 在任何旧状态 getter 可执行前读取已提交的白痴状态。 */
export function demonIdiotRevealed(world: World, actorId: number): boolean | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = b.players.get(actorId),
    cp = p?.checkpoint;
  if (
    !p ||
    !cp ||
    p.kind !== Role.Idiot ||
    !validBinding(b) ||
    !originalLife(p, world, true) ||
    !privateAuditCurrent(p, () => delegatedCurrent(b)) ||
    world.getComponent(actorId, COMPONENT.VotingRight) !== cp.vote ||
    demonVoteJson(cp.vote) !== cp.voteJson
  )
    throw new Error("demon_hunter_idiot_state_revoked");
  const state = ownDemonData(p.privateState, "idiot");
  const revealed = ownDemonData(state, "revealed");
  if (!exactDemonData(state, ["revealed"]) || typeof revealed !== "boolean")
    throw new Error("demon_hunter_idiot_state_revoked");
  return revealed;
}

/** 有限板子当前日只由最近已结算的夜产生。 */
export function demonRedMoonDay(world: World, actorId: number): number | null {
  const b = bindings.get(world),
    p = b?.players.get(actorId);
  if (!b || !p || String(p.kind) !== RED_MOON_ROLE) return null;
  demonHunterCheckpointPlayers(world, true);
  if (b.active || !originalLife(p, world, true)) return null;
  const day = [...b.nights.keys()].at(-1);
  const n = day === undefined ? null : b.nights.get(day);
  return n?.closed && n.frozen ? n.day : null;
}
export function demonRedMoonCanBlast(world: World, actorId: number): boolean {
  if (demonRedMoonDay(world, actorId) === null) return false;
  const b = bindings.get(world)!,
    p = b.players.get(actorId)!;
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state || state.blastDay !== null || state.exileDay !== null) return false;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  return wolves > 1 || state.lastWolfBlastPolicy === "ends_game";
}
export function commitDemonRedMoonBlast(
  world: World,
  actorId: number,
): { day: number; sealsNight: boolean } | null {
  const day = demonRedMoonDay(world, actorId);
  if (day === null || !demonRedMoonCanBlast(world, actorId)) return null;
  const b = bindings.get(world)!;
  const wolves = [...b.players.values()].filter(
    (player) => player.camp === Camp.Wolf && originalLife(player, world, true),
  ).length;
  if (!commitDemonRedMoonTransition(world, actorId, "blast", day)) return null;
  return { day, sealsNight: wolves > 1 };
}

/** 被延后的存活最后一狼只在普通来源已结算后到期。 */
export function demonRedMoonExpiry(world: World, day: number): number | null {
  const b = bindings.get(world);
  if (!b) return null;
  const p = [...b.players.values()].find((player) => String(player.kind) === RED_MOON_ROLE);
  if (!p) return null;
  demonHunterCheckpointPlayers(world, true);
  const n = b.active;
  if (!n || n.day !== day || n.closed || !n.frozen)
    throw new Error("red_moon_expiry_phase_invalid");
  const state = getRedMoonState(p.role, () => world.getComponent(p.id, COMPONENT.Camp));
  if (!state) throw new Error("red_moon_original_state_revoked");
  return state.exileDay === day - 1 && !state.expirySettled && originalLife(p, world, true)
    ? p.id
    : null;
}

export function isRedMoonBoard(world: World): boolean {
  const b = bindings.get(world);
  if (!b || ![...b.players.values()].some((p) => p.kind === Role.RedMoonApostle)) return false;
  if (!validBinding(b)) throw new Error("red_moon_original_state_revoked");
  return true;
}

/**
 * 负责原生猎魔板女巫请求绑定、共享最早截止时间，以及药印记可信读取的唯一实现。
 * 输入保留 World、turn／context、scope 和原库存引用；输出为请求当前性或只读可信查询，不授予用药权限。
 * 请求别名只在原生 scope／躯体和正文检查后绑定，过期、替换或非法原请求撤销交付，完成仍归原 scope。
 * 五个印记方法在本模块原初始化点捕获一次；原库存／原型、实例遮蔽和已退休展示名称按原次序拒绝。
 * 捕获表、请求 WeakMap 和 guard 保持同一所有者；只读查询不冻结实例、不复制库存或写来源／付款。
 */
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import {
  Phase,
  PotionType,
  bindRequestDeliveryGuard,
  type ActionRequest,
  type ToolCall,
  type World,
} from "../../../../core";
import { COMPONENT, StatusMark } from "../../../../core";
import {
  StatusMarksComponent,
  statusMarkSnapshot,
} from "../../../../core/domain/components/status_marks";
import { demonSnapshot, exactDemonData, ownDemonData } from "./state-slot";
/** 同一原请求的运行绑定；别名共享可提前的期限，World／上下文和current闭包不是序列化凭证。 */
interface Turn {
  world: World;
  original: object;
  originalContext: object;
  originalDeadline: unknown;
  targetCurrent: (targetId: number) => boolean;
  scope: object;
  current: () => boolean;
  json: string;
  deadline: number | null;
}
/** 每个真实别名保留原上下文与截止字段，记录本身不深复制请求或扩大资源许可。 */
interface Request {
  turn: Turn;
  context: object;
  deadline: unknown;
}
const requests = new WeakMap<object, Request>();
function body(request: object): string | null {
  try {
    const data = demonSnapshot(request, new Set(), 0, 16384) as Record<string, unknown>;
    return JSON.stringify(
      Object.fromEntries(Object.entries(data).filter(([key]) => key !== "deadlineAtMs")),
    );
  } catch {
    return null;
  }
}
function current(request: object, r: Request): boolean {
  return (
    r.turn.current() &&
    body(r.turn.original) === r.turn.json &&
    ownDemonData(r.turn.original, "context") === r.turn.originalContext &&
    ownDemonData(r.turn.original, "deadlineAtMs") === r.turn.originalDeadline &&
    body(request) === r.turn.json &&
    ownDemonData(request, "context") === r.context &&
    ownDemonData(request, "deadlineAtMs") === r.deadline &&
    (r.turn.deadline === null || r.turn.deadline > Date.now())
  );
}
function bindDemonNativeRequest(
  world: World,
  request: ActionRequest,
  scope: object,
  isCurrent: () => boolean,
  targetCurrent: (targetId: number) => boolean,
  spec: readonly [string, string, string],
): void {
  const json = body(request),
    context = ownDemonData(request, "context"),
    deadline = ownDemonData(request, "deadlineAtMs");
  if (
    !json ||
    !context ||
    typeof context !== "object" ||
    requests.has(request) ||
    request.phase !== Phase.Night ||
    request.context.stage !== spec[0] ||
    request.allowedTools.length !== 1 ||
    request.allowedTools[0] !== spec[1] ||
    request.context.ability_id !== spec[2] ||
    (deadline !== undefined &&
      (typeof deadline !== "number" || !Number.isFinite(deadline) || deadline <= Date.now()))
  )
    throw new Error("demon_hunter_native_witch_request_invalid");
  const turn: Turn = {
      world,
      original: request,
      originalContext: context,
      originalDeadline: deadline,
      targetCurrent,
      scope,
      current: isCurrent,
      json,
      deadline: deadline === undefined ? null : (deadline as number),
    },
    r = { turn, context, deadline };
  bindRequestDeliveryGuard(request, () => current(request, r), scope);
  requests.set(request, r);
  registerRequestAliasPropagation(request, 70, inheritDemonWitchDeadlineRequest);
}
export function bindDemonWitchRequest(
  world: World,
  request: ActionRequest,
  scope: object,
  isCurrent: () => boolean,
  targetCurrent: (id: number) => boolean,
): void {
  bindDemonNativeRequest(world, request, scope, isCurrent, targetCurrent, [
    "witch",
    "use_potion",
    "native:potion",
  ]);
}
export function bindDemonNativeNightRequest(
  world: World,
  request: ActionRequest,
  scope: object,
  isCurrent: () => boolean,
  targetCurrent: (id: number) => boolean,
  kind: "seer_check" | "guard",
): void {
  bindDemonNativeRequest(
    world,
    request,
    scope,
    isCurrent,
    targetCurrent,
    kind === "guard"
      ? ["guard", "guard", "native:guard"]
      : ["seer", "check_identity", "native:seer_check"],
  );
}
export function readDemonNativeNightTool(
  value: unknown,
): Extract<ToolCall, { name: "check_identity" | "guard" }> | null {
  try {
    const call = demonSnapshot(value);
    if (
      !exactDemonData(call, ["name", "args"]) ||
      !exactDemonData(call.args, call.name === "guard" ? ["target_id", "abstain"] : ["target_id"])
    )
      return null;
    const target = call.args.target_id,
      positive = Number.isSafeInteger(target) && (target as number) > 0;
    if (call.name === "check_identity")
      return positive ? (call as unknown as Extract<ToolCall, { name: "check_identity" }>) : null;
    if (
      call.name !== "guard" ||
      !(
        (target === null && call.args.abstain === true) ||
        (positive && call.args.abstain === false)
      )
    )
      return null;
    return call as unknown as Extract<ToolCall, { name: "guard" }>;
  } catch {
    return null;
  }
}
export function demonWitchRequestCurrent(world: World, request: object): boolean {
  const r = requests.get(request);
  return !!r && r.turn.world === world && current(request, r);
}
/** 通过原绑定与正文／同一上下文检查的别名共享最早截止时间；在原位置记录新的更早期限。 */
export function inheritDemonWitchDeadlineRequest(
  request: ActionRequest,
  clone: ActionRequest,
): void {
  const r = requests.get(request);
  if (
    !r ||
    !current(request, r) ||
    body(clone) !== r.turn.json ||
    ownDemonData(clone, "context") !== r.context ||
    requests.has(clone)
  )
    return;
  const deadline = ownDemonData(clone, "deadlineAtMs");
  if (
    typeof deadline !== "number" ||
    !Number.isFinite(deadline) ||
    deadline <= Date.now() ||
    (r.turn.deadline !== null && deadline > r.turn.deadline)
  )
    return;
  const copied: Request = { turn: r.turn, context: r.context, deadline };
  bindRequestDeliveryGuard(clone, () => current(clone, copied), r.turn.scope);
  r.turn.deadline = deadline;
  requests.set(clone, copied);
  registerRequestAliasPropagation(clone, 70, inheritDemonWitchDeadlineRequest);
}
export function readDemonPotionTool(
  value: unknown,
): Extract<ToolCall, { name: "use_potion" }> | null {
  try {
    const call = demonSnapshot(value);
    if (
      !exactDemonData(call, ["name", "args"]) ||
      call.name !== "use_potion" ||
      !exactDemonData(call.args, ["target_id", "potion_type"]) ||
      !Number.isSafeInteger(call.args.target_id) ||
      (call.args.target_id as number) < 1 ||
      ![PotionType.Heal, PotionType.Poison, PotionType.None].includes(
        call.args.potion_type as PotionType,
      )
    )
      return null;
    return call as unknown as Extract<ToolCall, { name: "use_potion" }>;
  } catch {
    return null;
  }
}

// 五方法只在原请求 WeakMap 建立之后的模块初始化点捕获；按既定顺序取 descriptor.value，不执行方法。
// 表是唯一闭包基准，不在每次查询重捕获，也不因公开端口而提前到另一个模块初始化。
const trustedMarkMethods = Object.fromEntries(
  ["has", "add", "remove", "clear", "values"].map((key) => [
    key,
    Object.getOwnPropertyDescriptor(StatusMarksComponent.prototype, key)!.value,
  ]),
);
/** 原库存／方法身份的只读检查；无组件仍按原规则返回 true，不表示有药、合法目标或行动已提交。 */
export function demonWitchMarksSafe(world: World, targetId: number): boolean {
  const marks = world.getComponent(targetId, COMPONENT.StatusMarks);
  if (!marks) return true;
  // 先核原工厂私有库存，再查精确原型；不用实例 has 方法读印记，也不执行遮蔽方法。
  if (
    !statusMarkSnapshot(marks, StatusMark.PoisonMark) ||
    Object.getPrototypeOf(marks) !== StatusMarksComponent.prototype
  )
    return false;
  // 原顺序逐个查实例 descriptor 和原型方法身份，首个失败即停止；随后才查实例／原型旧展示名称。
  // 展示属性退出领域，不把旧名称的消失变成修改方法身份的绕过入口。
  return Object.entries(trustedMarkMethods).every(
    ([key, method]) =>
      !Object.getOwnPropertyDescriptor(marks, key) &&
      Object.getOwnPropertyDescriptor(StatusMarksComponent.prototype, key)?.value === method,
  ) &&
    !Object.getOwnPropertyDescriptor(marks, "renderPrompt") &&
    !Object.getOwnPropertyDescriptor(StatusMarksComponent.prototype, "renderPrompt");
}
export function demonWitchRequestTargetCurrent(
  world: World,
  request: object,
  targetId: number,
): boolean {
  const r = requests.get(request);
  return (
    !!r &&
    r.turn.world === world &&
    current(request, r) &&
    r.turn.targetCurrent(targetId) &&
    demonWitchMarksSafe(world, targetId)
  );
}

controls.text:
/**
 * 负责有限猎魔人原猎杀回合的请求、回复复验和选择交付。输入为原 World、事件、夜号与惰性构造依赖；
 * 输出原选择事实，生命／库存／付款归 authority；请求绑定先于等待，回复后按原次序复验并提交。
 * 原 turn 开启后才在 try 内读取工厂类，失败保已发生前缀并关闭原许可，不重试或补交选择。
 */
import {
  Phase,
  type World,
  type GameEvent,
  type ActionProvider,
  type ActionStage,
  type ToolName,
  type ToolCall,
} from "../../../../core";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { DEMON_HUNTER_POLICY, readDemonHuntTool } from "./state-slot";
import {
  demonHunterActorId,
  openDemonHunterTurn,
  closeDemonHunterTurn,
  bindDemonHunterRequest,
  authorizedDemonHunter,
  canSubmitDemonHunt,
  commitDemonHunt,
} from "./authority";
export interface DemonHunterChoiceFact {
  readonly policy: typeof DEMON_HUNTER_POLICY;
  readonly actorId: number;
  readonly day: number;
  readonly targetId: number | null;
}
/** 原有限猎魔人行动；具体原体／夜许可仍由 authority 复验，构造依赖不是选择或付款许可。 */
export async function executeDemonHunterTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  /** 原 new 点晚读构造器；不会复用阶段工厂或据依赖授予猎杀许可。 */
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<Readonly<DemonHunterChoiceFact>> {
  const { world, gateway, events, provider, day } = input,
    actorId = demonHunterActorId(world);
  if (actorId === null) throw new Error("demon_hunter_actor_unavailable");
  const scope = openDemonHunterTurn(world);
  try {
    // 原 turn 已开且位于 try 内；构造读取或 create 失败仍由原 finally 关闭许可。
    const request = new input.construction.requestFactory(world, events, day).create({
      phase: Phase.Night,
      actorId,
      allowedTools: ["demon_hunt" as ToolName],
      stage: "demon_hunter" as ActionStage,
      requiresAction: true,
      summary: { key: "request.summary.night_action" },
      context: { allow_fallback: false, action_failure_policy: "error" },
    });
    bindDemonHunterRequest(world, request);
    if (!authorizedDemonHunter(world, actorId, Phase.Night, day, scope))
      throw new Error("demon_hunter_turn_revoked");
    const raw = await provider.getAction(request);
    if (!authorizedDemonHunter(world, actorId, Phase.Night, day, scope))
      throw new Error("demon_hunter_turn_revoked");
    const call = readDemonHuntTool(raw);
    if (!call || !canSubmitDemonHunt(world, actorId, Phase.Night, day, scope, call))
      throw new Error("demon_hunter_required_action_invalid");
    const valid = gateway.validateAndSanitize(world, actorId, call as unknown as ToolCall, {
      phase: Phase.Night,
      day,
      demonHunterScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw new Error("demon_hunter_action_invalid");
    const choice = commitDemonHunt(world, scope, call);
    if (!choice) throw new Error("demon_hunter_action_commit_failed");
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    return Object.freeze({
      policy: DEMON_HUNTER_POLICY,
      actorId,
      day: choice.day,
      targetId: choice.targetId,
    });
  } finally {
    closeDemonHunterTurn(scope);
  }
}

/**
 * 负责有限猎魔人板的原生女巫行动、真实用药交付及夜间来源封存。
 * 输入为原 World、夜号、刀口、网关与 Provider；输出为行动回执、已付救／毒交付及封存来源。
 * 两条原毒分支在原 claim 创建位置附加 sourced intent，复用已捕获 source/target/day。
 * 保留瓶数付款、commit、交付缓存、事实发布与关闭的原次序；后续失败不回滚已提交前缀。
 * 新来源 metadata 与 life 句柄仅运行时使用，不加入事件、player DTO 或归档字段。
 */
import {
  COMPONENT,
  Phase,
  PotionType,
  StatusMark,
  settleRequestDelivery,
  type ActionProvider,
  type GameEvent,
  type World,
} from "../../../../core";
import {
  StatusMarksComponent,
  statusMarkSnapshot,
} from "../../../../core/domain/components/status_marks";
import {
  captureNightLife,
  originalPoisonIntent,
  type NightPoisonClaim,
} from "../../../../core/domain/night_effects";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { recordNightAbilityUse, type NightAbility } from "../abilities";
import {
  openDemonWitchTurnFrame,
  demonHunterFreezeDay,
  demonWitchRequiredThisNight,
} from "./authority";
import {
  bindDemonWitchRequest,
  demonWitchRequestCurrent,
  readDemonPotionTool,
  demonWitchRequestTargetCurrent,
  demonWitchMarksSafe,
} from "./native_potion_requests";
import {
  captureDemonNativePoison,
  commitDemonNativePoison,
  freezeDemonNightSources,
  type DemonNightSources,
} from "./native_poison";
import {
  openNativePoisonContribution,
  commitNativePoisonContribution,
  sealNativePoisonContribution,
  lateUnknownPoisonContribution,
  type NativePoisonContributions,
} from "./poison_contribution";

import {
  openNativeHealContribution,
  commitNativeHealContribution,
  sealNativeHealContribution,
  lateUnknownHealContribution,
  type NativeHealContributions,
} from "./heal_contribution";
/** 已付救药的运行交付；原生命查询与贡献封存回调不能进入玩家 DTO 或归档。 */
interface DeliveredDemonHeal {
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativeHealContributions>;
}
const deliveredHeals = new WeakMap<World, Map<number, Readonly<DeliveredDemonHeal>>>();
/**
 * 已付原生毒的运行交付；proof 仅在毒向猎魔人且原生免疫来源被登记时存在。
 * 普通原生毒仍保留 claim 与独立贡献；null proof 不表示没有付款或没有毒来源。
 */
export interface DeliveredDemonPoison {
  readonly proof: object | null;
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativePoisonContributions>;
}
const nativeAddMark = StatusMarksComponent.prototype.add;
const delivered = new WeakMap<World, Map<number, Readonly<DeliveredDemonPoison> | null>>();
/**
 * 私有 token 对应的唯一封存账本，绑定原 World 与夜号。贡献在普通伤害清标记前捕获；
 * frozen 只在底层来源冻结成功后置位，后续构造失败也不恢复该 token 的可用性。
 */
interface Sealed {
  world: World;
  day: number;
  poison: Readonly<DeliveredDemonPoison> | null;
  contributions: Readonly<NativePoisonContributions> | null;
  heal: Readonly<DeliveredDemonHeal> | null;
  healContributions: Readonly<NativeHealContributions> | null;
  frozen: boolean;
}
const sealedSources = new WeakMap<object, Sealed>();
const sealedNights = new WeakMap<World, Set<number>>();
/** 本次行动交付结果；used 只区分用药与放弃，poison 不承载救药回执。 */
export interface DemonWitchTurnResult {
  readonly poison: Readonly<DeliveredDemonPoison> | null;
  readonly used: boolean;
}
/** 原有限猎魔人板中唯一原生女巫的执行路径；await 后复验原请求与目标，最终关闭交付窗口。 */
export async function executeDemonWitchTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  wolfTarget: number | null;
  /** 只在原 new 点读取；原 frame 开启／夜复位已发生，依赖不授予用药资格。 */
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<Readonly<DemonWitchTurnResult>> {
  const { world, gateway, events, provider, day, wolfTarget } = input,
    frame = openDemonWitchTurnFrame(world);
  if (!frame || frame.day !== day) throw new Error("demon_hunter_native_witch_unavailable");
  const ability = frame.ability as NightAbility<"potion">,
    scope = Object.freeze({});
  let closed = false;
  if (!world.entityIds().every((id) => demonWitchMarksSafe(world, id)))
    throw new Error("demon_hunter_native_marks_invalid");
  // frame 开启和 marks 检查先完成；原 new／bind 在 try 外，失败保留复位前缀，不加新的 finally。
  const request = new input.construction.requestFactory(world, events, day).create({
    phase: Phase.Night,
    actorId: frame.witchId,
    allowedTools: ["use_potion"],
    stage: "witch",
    requiresAction: true,
    summary: { key: "request.summary.night_action" },
    context: {
      ability_id: "native:potion",
      allow_fallback: false,
      action_failure_policy: "error",
      ...(ability.state.heal > 0 ? { wolf_target: wolfTarget } : {}),
    },
  });
  bindDemonWitchRequest(
    world,
    request,
    scope,
    () => !closed && frame.isCurrent(),
    frame.targetCurrent,
  );
  const authorized = () => demonWitchRequestCurrent(world, request);
  try {
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const raw = await provider.getAction(request);
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const call = readDemonPotionTool(raw);
    if (!call || !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
      throw new Error("demon_hunter_native_witch_invalid");
    const candidateMarks = world.getComponent(call.args.target_id, COMPONENT.StatusMarks);
    if (
      candidateMarks &&
      (!statusMarkSnapshot(candidateMarks, StatusMark.PoisonMark) ||
        Object.getPrototypeOf(candidateMarks) !== StatusMarksComponent.prototype ||
        Object.getOwnPropertyDescriptor(candidateMarks, "has"))
    )
      throw new Error("demon_hunter_native_marks_invalid");
    const checked = gateway.validateAndSanitize(world, frame.witchId, call, {
      phase: Phase.Night,
      day,
      abilityId: "native:potion",
      deferOperation: true,
    });
    if (
      !checked.ok ||
      !checked.sanitizedCall ||
      !authorized() ||
      !demonWitchRequestTargetCurrent(world, request, call.args.target_id)
    )
      throw new Error("demon_hunter_native_witch_invalid");
    const targetId = call.args.target_id,
      potion = call.args.potion_type;
    const source = captureNightLife(world, frame.witchId),
      target = captureNightLife(world, targetId);
    if (!source || !target) throw new Error("demon_hunter_native_witch_revoked");
    Object.freeze(source);
    Object.freeze(target);
    let poison: Readonly<DeliveredDemonPoison> | null = null;
    const native =
      potion === PotionType.Poison && targetId === frame.demonId
        ? captureDemonNativePoison(world, frame.witchId, ability, targetId)
        : null;
    if (potion === PotionType.Poison && targetId === frame.demonId && !native)
      throw new Error("demon_hunter_native_poison_unavailable");
    let marks = world.getComponent(targetId, COMPONENT.StatusMarks);
    if (potion !== PotionType.None && !marks) {
      marks = new StatusMarksComponent();
      world.addComponent(targetId, COMPONENT.StatusMarks, marks);
    }
    const contribution =
      potion === PotionType.Poison && marks
        ? openNativePoisonContribution(world, targetId, marks)
        : null;
    const healContribution =
      potion === PotionType.Heal && marks
        ? openNativeHealContribution(world, targetId, marks)
        : null;
    // 先登记使用、写标记及扣瓶，再由 frame 核对真实库存提交；失败不伪造付款回滚。
    recordNightAbilityUse(ability, day, potion !== PotionType.None);
    if (potion !== PotionType.None) {
      nativeAddMark.call(
        marks!,
        potion === PotionType.Heal ? StatusMark.HealMark : StatusMark.PoisonMark,
      );
      ability.state[potion]--;
      ability.state[potion === PotionType.Heal ? "healUsedThisNight" : "poisonUsedThisNight"] =
        true;
    }
    if (!frame.commit(potion)) throw new Error("demon_hunter_native_witch_commit_failed");
    // frame 已提交后先登记真实贡献；随后 proof、交付或事实发布失败仍保留这段已付前缀。
    if (contribution) commitNativePoisonContribution(contribution);
    if (healContribution) {
      commitNativeHealContribution(healContribution);
      const heals = deliveredHeals.get(world) ?? new Map<number, Readonly<DeliveredDemonHeal>>();
      if (heals.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
      heals.set(
        day,
        Object.freeze({
          claim: Object.freeze({
            source,
            target,
            isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
          }),
          lateUnknown: () => lateUnknownHealContribution(healContribution),
          sealContribution: () => sealNativeHealContribution(healContribution),
        }),
      );
      deliveredHeals.set(world, heals);
    }
    if (native && contribution) {
      const proof = commitDemonNativePoison(native);
      if (!proof) throw new Error("demon_hunter_native_poison_commit_failed");
      poison = Object.freeze({
        proof,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution),
        sealContribution: () => sealNativePoisonContribution(contribution),
      });
    } else if (potion === PotionType.Poison) {
      // 普通原生毒不持有猎魔人免疫 proof；来源与后续独立毒贡献仍必须保留。
      poison = Object.freeze({
        proof: null,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution!),
        sealContribution: () => sealNativePoisonContribution(contribution!),
      });
    }
    const nights = delivered.get(world) ?? new Map<number, Readonly<DeliveredDemonPoison> | null>();
    if (nights.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
    nights.set(day, poison);
    delivered.set(world, nights);
    settleRequestDelivery(scope, true);
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId: frame.witchId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    events.push({
      timestamp: Date.now(),
      type: potion === PotionType.None ? "witch_potion_skipped" : "witch_potion_used",
      payload: {
        actorId: frame.witchId,
        targetId,
        potionType: potion,
      },
    } as GameEvent);
    return Object.freeze({ poison, used: potion !== PotionType.None });
  } finally {
    closed = true;
    settleRequestDelivery(scope, false);
  }
}

/** 在普通伤害清除标记前封存原交付贡献；返回仅本控制器登记的运行 token，同夜不得重封。 */
export function sealDeliveredDemonWitchSources(world: World, day: number): object {
  if (
    demonHunterFreezeDay(world) !== day ||
    (demonWitchRequiredThisNight(world) && !delivered.get(world)?.has(day))
  )
    throw new Error("demon_hunter_native_sources_missing");
  const seen = sealedNights.get(world) ?? new Set<number>();
  if (seen.has(day)) throw new Error("demon_hunter_native_sources_already_sealed");
  const poison = delivered.get(world)?.get(day) ?? null;
  const contributions = poison?.sealContribution() ?? null;
  const heal = deliveredHeals.get(world)?.get(day) ?? null,
    healContributions = heal?.sealContribution() ?? null;
  const token = Object.freeze({});
  sealedSources.set(token, {
    world,
    day,
    poison,
    contributions,
    heal,
    healContributions,
    frozen: false,
  });
  seen.add(day);
  sealedNights.set(world, seen);
  return token;
}
/** 冻结后的来源结果；救／毒覆盖只重算本控制器涉及的目标，不替代其它独立来源。 */
export interface DeliveredDemonNightSources extends DemonNightSources {
  readonly poisonOverrides: readonly Readonly<{ targetId: number; poison: boolean }>[];
  readonly healOverrides: readonly Readonly<{ targetId: number; heal: boolean }>[];
}
/**
 * 完整来源只取真实控制器与私有 token，不从 Tape 事实或调用方 metadata 恢复授权。
 * 先查询原来源当前性及迟到的独立贡献，再冻结底层毒／狩猎；底层成功后立即消费封存账本。
 * 猎魔人的原生毒免疫只抵消该原生贡献，unknown 或迟到独立毒继续参与目标的最终覆盖。
 */
export function freezeDeliveredDemonNightSources(
  world: World,
  token: object,
  faultId: string | null = null,
): Readonly<DeliveredDemonNightSources> {
  const sealed = sealedSources.get(token),
    day = demonHunterFreezeDay(world);
  if (!sealed || sealed.world !== world || sealed.day !== day || sealed.frozen)
    throw new Error("demon_hunter_native_sources_invalid");
  const poison = sealed.poison,
    contributions = sealed.contributions;
  const originalSourceCurrent = poison?.claim.isCurrent?.() === true;
  const lateUnknown = poison?.lateUnknown() ?? false;
  const healCurrent = sealed.heal?.claim.isCurrent?.() === true,
    lateHeal = sealed.heal?.lateUnknown() ?? false;
  const result = freezeDemonNightSources(world, poison?.proof ? [poison.proof] : [], faultId);
  sealed.frozen = true;
  const immunity =
    !!poison?.proof &&
    contributions?.native === true &&
    originalSourceCurrent &&
    result.poisonImmunities.length === 1;
  return Object.freeze({
    hunt: result.hunt,
    healOverrides: Object.freeze(
      sealed.heal && sealed.healContributions
        ? [
            Object.freeze({
              targetId: sealed.heal.claim.target.id,
              heal:
                sealed.healContributions.unknown ||
                lateHeal ||
                (sealed.healContributions.native && healCurrent),
            }),
          ]
        : [],
    ),
    poisonImmunities: Object.freeze(immunity ? [...result.poisonImmunities] : []),
    poisonOverrides: Object.freeze(
      poison && contributions
        ? [
            Object.freeze({
              targetId: poison.claim.target.id,
              poison:
                contributions.unknown ||
                lateUnknown ||
                (contributions.native && originalSourceCurrent && !immunity),
            }),
          ]
        : [],
    ),
  });
}

/**
 * 负责有限猎魔人板原生守卫／预言家的严格交付；输入原夜上下文、frame及惰性构造依赖，输出原库存提交与事实。
 * 原体、目标与付款仍由 frame／请求 owner 校验；成功先交付再发事实，提交失败沿原 finally 结算 false。
 * 工厂构造和绑定原在 try 之前，构造抛错不会进入该 finally；不新增清理或替换捕获的原库存／操作。
 */
import {
  Camp,
  Phase,
  StatusMark,
  settleRequestDelivery,
  COMPONENT,
  type StatusMarksComponent,
} from "../../../../core";
import { StatusMarksComponent as Marks } from "../../../../core/domain/components/status_marks";
import { captureNightLife } from "../../../../core/domain/night_effects";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { NightStageContext } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import { recordOwnNightAction } from "../night_action_history";
import { demonNativeNightActor, openDemonNativeNightFrame } from "./authority";
import {
  bindDemonNativeNightRequest,
  demonWitchRequestCurrent,
  demonWitchRequestTargetCurrent,
  readDemonNativeNightTool,
} from "./native_potion_requests";
import { openNativeGuardContribution, commitNativeGuardContribution } from "./guard_contribution";
const nativeAdd = Marks.prototype.add;
/** 仅此有限板的原生预言家／守卫进入该路径；赠予、复制及其他板仍沿各自原机制。 */
export async function executeDemonNativeNight(
  ctx: NightStageContext,
  kind: "seer_check" | "guard",
): Promise<void> {
  const { world } = ctx,
    day = ctx.currentDay(),
    actor = demonNativeNightActor(world, kind);
  if (!actor) return;
  const frame = openDemonNativeNightFrame(world, actor.actorId, actor.ability, kind, day);
  if (!frame) throw new Error("demon_hunter_native_night_unavailable");
  const guard = kind === "guard",
    name = guard ? "guard" : "check_identity",
    scope = Object.freeze({});
  let closed = false,
    committed = false;
  // callee 先于 ctx.events 读取；原构造／绑定处于 try 外，保留失败边界而不补清理。
  const request = new ctx.requestFactory(world, ctx.events, day).create({
    phase: Phase.Night,
    actorId: actor.actorId,
    allowedTools: [name],
    stage: guard ? "guard" : "seer",
    requiresAction: true,
    summary: { key: "request.summary.night_action" },
    context: {
      ability_id: `native:${kind}`,
      allow_fallback: false,
      action_failure_policy: "error",
    },
  });
  bindDemonNativeNightRequest(
    world,
    request,
    scope,
    () => !closed && frame.isCurrent(),
    frame.targetCurrent,
    kind,
  );
  const authorized = () => demonWitchRequestCurrent(world, request);
  try {
    if (!authorized()) throw new Error("demon_hunter_native_night_revoked");
    const raw = await ctx.actionProvider.getAction(request);
    if (!authorized()) throw new Error("demon_hunter_native_night_revoked");
    const call = readDemonNativeNightTool(raw);
    if (
      !call ||
      call.name !== name ||
      (call.args.target_id !== null &&
        !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
    )
      throw new Error("demon_hunter_native_night_invalid");
    const valid = ctx.toolGateway.validateAndSanitize(world, actor.actorId, call, {
      phase: Phase.Night,
      day,
      abilityId: `native:${kind}`,
      deferOperation: true,
    });
    if (
      !authorized() ||
      !valid.ok ||
      !valid.sanitizedCall ||
      (call.args.target_id !== null &&
        !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
    )
      throw new Error("demon_hunter_native_night_invalid");
    const targetId = call.args.target_id;
    if (guard) {
      const target = targetId === null ? null : captureNightLife(world, targetId);
      const marks = targetId === null ? null : world.getComponent(targetId, COMPONENT.StatusMarks);
      if (targetId !== null && (!target || !marks))
        throw new Error("demon_hunter_native_guard_target_invalid");
      const contribution =
        targetId !== null && marks ? openNativeGuardContribution(world, targetId, marks) : null;
      if (!authorized() || !frame.commitGuard(targetId))
        throw new Error("demon_hunter_native_guard_commit_revoked");
      if (targetId !== null && target && marks && contribution) {
        nativeAdd.call(marks, StatusMark.GuardMark);
        commitNativeGuardContribution(contribution);
        (ctx.state.guardClaims ??= []).push({
          target: Object.freeze(target),
          marks,
          isCurrent: frame.sourceCurrent,
          contribution,
        });
      }
      committed = true;
      settleRequestDelivery(scope, true);
      ctx.events.push({
        timestamp: Date.now(),
        type: "guard_applied",
        payload: { actorId: actor.actorId, abstain: targetId === null, targetId },
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "guard_applied",
        actorId: actor.actorId,
        phase: Phase.Night,
        status: "ok",
        output: { abstain: targetId === null, target_id: targetId },
      });
      if (targetId !== null)
        recordOwnNightAction(world, actor.actorId, day, "guard", targetId, false);
    } else {
      if (targetId === null) throw new Error("demon_hunter_native_seer_target_invalid");
      const result = resolveInspection(world, targetId, "camp", ctx.roleCatalog);
      if (!result || !authorized() || !frame.commitSeer(targetId, result))
        throw new Error("demon_hunter_native_seer_commit_revoked");
      committed = true;
      settleRequestDelivery(scope, true);
      const isWerewolf = result.camp === Camp.Wolf;
      ctx.state.seerChecks.push({
        seerId: actor.actorId,
        targetId,
        isWerewolf,
        result: { ...result },
      });
      recordOwnNightAction(world, actor.actorId, day, "check", targetId, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "seer_checked",
        payload: { actorId: actor.actorId, targetId, isWerewolf, result: { ...result } },
      });
    }
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId: actor.actorId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
  } finally {
    closed = true;
    if (!committed) settleRequestDelivery(scope, false);
  }
}

/**
 * 负责完整行动接收预检：允许工具、首用 JSON schema、原参数修复、机制请求作用域和领域规则。
 * 输入为同一 World、原请求与外来工具参数；输出为脱离后的合法候选或原结构化拒绝。
 * 每实例只持有原 schema 缓存和不写第二 Tape 校验的 Gateway；schema 与具体 scope 仍按原时点晚读。
 * 本 owner 不消耗库存、提交领域动作或 settle 完成责任；选择／截止窗口由 AI ActionTurn 独立拥有。
 */
import { nobleBodyRequestScope } from "../mechanisms/roles/noble_secret_body/ports";
import { animalRequestScope } from "../mechanisms/roles/animal_dream/ports";
import { fragrantPairRequestScope } from "../mechanisms/roles/fragrant_pair_seer/ports";
import {
  demonWitchRequestTargetCurrent,
  demonWitchRequestCurrent,
  readDemonNativeNightTool,
  readDemonPotionTool,
} from "../mechanisms/roles/demon_hunter/ports";
import {
  demonHunterRequestScope,
  canSubmitDemonHunt,
  demonHunterActorId,
} from "../mechanisms/roles/demon_hunter/ports";
import { readDemonHuntTool } from "../mechanisms/roles/demon_hunter/ports";
import {
  ghostBrideRequestScope,
  weddingSetup,
} from "../mechanisms/roles/ghost_bride/ports";
import { readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import { lonelyGirlRequestScope } from "../mechanisms/roles/lonely_girl/ports";
import { readLonelyGirlTool } from "../mechanisms/roles/lonely_girl/ports";
import { wildChildRequestScope } from "../mechanisms/roles/wild_child/ports";
import { readWildChildTool } from "../mechanisms/roles/wild_child/ports";
import { shapeshifterRequestScope } from "../mechanisms/roles/shapeshifter/ports";
import { thiefRequestScope } from "../mechanisms/roles/thief/ports";
import { readThiefChoice } from "../mechanisms/roles/thief/ports";
import { wallRequestScope } from "../mechanisms/events/wall_notes/ports";
import { z, type ZodType } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  DEATH_SHOT_STAGES,
  type ActionRequest,
  type ToolCall,
  type ToolName,
} from "../../core/domain";
import { World } from "../../core/domain/world";
import { ActionValidator } from "./action_validator";
import { ToolGateway } from "./tool_gateway";
import {
  getDefaultToolCallRepairRegistry,
  getDefaultToolValidationRuleRegistry,
  type ToolCallRepairRegistry,
  type ToolValidationRuleRegistry,
} from "../mechanisms";
import {
  getDefaultToolSpecRegistry,
  type ToolSpecRegistry,
} from "../mechanisms/registries/tool_spec_registry";
import { evaluateTurnConstraints, resolveTurnConstraints } from "./turn-constraints";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/** 只描述预检结果，不表示领域已付款或生效；可选回合字段保留原拒绝结构接受集合。 */
export type GameActionValidation =
  | { ok: true; action: ToolCall }
  | {
      ok: false;
      error: string;
      message: string;
      details?: string[];
      expected_turn_id?: string;
      received_turn_id?: unknown;
    };

/**
 * 选择窗口的类型接口只声明原 locale 与预检函数，不提供写方法或领域完成接口。
 * 运行对象仍是原接收器和 World；这是消费契约，不是新的进程隔离或运行权限屏障。
 */
export interface ActionPreflightPort {
  readonly world: { readonly locale: Locale };
  validate(request: ActionRequest, name: string, rawArgs: unknown): GameActionValidation;
}
type Validation = GameActionValidation;

/** 预检只形成候选；实际应用与资源消费仍由引擎和具体机制提交。 */
export class ActionReception {
  private readonly schemas = new Map<ToolName, ZodType>();
  private readonly gateway: ToolGateway;

  constructor(
    readonly world: World,
    private readonly repair: ToolCallRepairRegistry = getDefaultToolCallRepairRegistry(),
    private readonly specs: ToolSpecRegistry = getDefaultToolSpecRegistry(),
    rules: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
  ) {
    // 这里仍关闭领域校验的 Tape 记录，避免接收预检制造第二次 validation 操作。
    this.gateway = new ToolGateway(new ActionValidator(rules, false));
  }

  validate(request: ActionRequest, name: string, rawArgs: unknown): Validation {
    const fail = (code: string) => toolFailure(this.world.locale, code);
    if (!request.allowedTools.includes(name as ToolName) || name === "report_bug") {
      return fail("tool_not_allowed_in_this_turn");
    }
    const tool = name as ToolName;
    const spec = this.specs.get(tool);
    if (!spec || rawArgs === null || typeof rawArgs !== "object" || Array.isArray(rawArgs)) {
      return fail("invalid_tool_arguments");
    }
    // 同一工具只在首个合法参数形态的调用建立 schema；建图失败不先写缓存，后续 properties 仍原位读取。
    let schema = this.schemas.get(tool);
    if (!schema) {
      schema = z.fromJSONSchema(spec.parameters);
      this.schemas.set(tool, schema);
    }
    // 保留原数字字符串修复；不把布尔／文本按 truthiness 或 String() 宽转，也不补缺少的必填参数。
    const wallCall = tool === "write_note" ? readWallTool({ name: tool, args: rawArgs }) : null;
    if (tool === "write_note" && !wallCall) return fail(RuleError.WallNoteText);
    const initialChoice = tool === "choose_thief_card" || tool === "choose_shapeshifter_card";
    const thiefSlot = initialChoice ? readThiefChoice(rawArgs) : undefined;
    if (initialChoice && thiefSlot === undefined)
      return fail(
        tool === "choose_thief_card" ? RuleError.ThiefChoice : RuleError.ShapeshifterChoice,
      );
    if (tool === "choose_admired_player" && !readLonelyGirlTool({ name: tool, args: rawArgs }))
      return fail(RuleError.LonelyGirlChoice);
    const wildCall =
      tool === "choose_wild_model" ? readWildChildTool({ name: tool, args: rawArgs }) : null;
    if (tool === "choose_wild_model" && !wildCall) return fail(RuleError.WildChildChoice);
    const weddingTool =
      [
        "choose_bridegroom",
        "choose_wedding_witness",
        "speak_to_partner",
        "wedding_kill_vote",
      ].includes(tool) ||
      (tool === "kill_vote" && weddingSetup(this.world) !== null);
    const weddingCall = weddingTool ? readWeddingTool({ name: tool, args: rawArgs }) : null;
    if (weddingTool && !weddingCall) return fail(RuleError.GhostBrideChoice);
    const demonCall =
      name === "demon_hunt" ? readDemonHuntTool({ name: tool, args: rawArgs }) : null;
    if (
      name === "demon_hunt" &&
      (!demonCall ||
        !canSubmitDemonHunt(
          this.world,
          request.actorId,
          request.phase,
          request.context.day,
          demonHunterRequestScope(this.world, request),
          demonCall,
        ))
    )
      return fail(RuleError.ToolMismatch);
    const demonNative =
      (tool === "check_identity" || tool === "guard") && demonHunterActorId(this.world) !== null;
    const nativeCall = demonNative ? readDemonNativeNightTool({ name: tool, args: rawArgs }) : null;
    if (
      demonNative &&
      (!nativeCall ||
        !demonWitchRequestCurrent(this.world, request) ||
        (nativeCall.args.target_id !== null &&
          !demonWitchRequestTargetCurrent(this.world, request, nativeCall.args.target_id)))
    )
      return fail(RuleError.ToolMismatch);
    const demonWitch = tool === "use_potion" && demonHunterActorId(this.world) !== null;
    const potionCall = demonWitch ? readDemonPotionTool({ name: tool, args: rawArgs }) : null;
    if (
      demonWitch &&
      (!potionCall ||
        !demonWitchRequestTargetCurrent(this.world, request, potionCall.args.target_id))
    )
      return fail(RuleError.ToolMismatch);
    const input = (
      potionCall
        ? potionCall.args
        : demonCall
          ? demonCall.args
          : weddingCall
            ? weddingCall.args
            : wildCall
              ? wildCall.args
              : initialChoice
                ? { slot: thiefSlot }
                : wallCall
                  ? wallCall.args
                  : { ...rawArgs }
    ) as Record<string, unknown>;
    const properties = spec.parameters.properties as
      Record<string, { type?: string | string[] }> | undefined;
    for (const [key, value] of Object.entries(input)) {
      const type = properties?.[key]?.type;
      const numeric =
        type === "number" ||
        type === "integer" ||
        (Array.isArray(type) && (type.includes("number") || type.includes("integer")));
      if (numeric && typeof value === "string" && /^\d+$/.test(value)) input[key] = Number(value);
    }
    const parsed = schema.safeParse(input);
    if (!parsed.success) return fail("invalid_tool_arguments");
    const args = this.repair.coerceArgs(tool, parsed.data as Record<string, unknown>, {
      actorId: request.actorId,
    });
    if (!args || !schema.safeParse(args).success) return fail("invalid_tool_arguments");
    const call = { name: tool, args } as ToolCall;
    const deathStage =
      DEATH_SHOT_STAGES.includes(request.context.stage) ||
      request.context.stage === "last_words" ||
      request.context.stage === "sheriff_badge_choice";
    const deathTool =
      (tool === "choose_badge_successor" &&
        request.context.stage === "sheriff_badge_choice" &&
        request.context.trigger === "badge_handoff") ||
      (tool === "shoot" &&
        DEATH_SHOT_STAGES.includes(request.context.stage) &&
        request.context.trigger === "on_death") ||
      (tool === "speak" &&
        request.context.stage === "last_words" &&
        request.context.trigger === "last_words");
    if (
      deathStage &&
      (!deathTool ||
        !this.world.hasDeathAction(
          request.actorId,
          tool,
          request.phase,
          request.context.day,
          request.context.death_action_id,
          request.context.ability_id,
        ))
    ) {
      return fail(RuleError.DeathActionUnavailable);
    }
    // 机制 scope 按下面原字段顺序逐个读取；不提前缓存请求许可或绕过 Gateway 的提交前规则。
    const checked = this.gateway.validateAndSanitize(this.world, request.actorId, call, {
      phase: request.phase,
      day: request.context.day,
      thiefScope: thiefRequestScope(this.world, request),
      shapeshifterScope: shapeshifterRequestScope(this.world, request),
      lonelyGirlScope: lonelyGirlRequestScope(this.world, request),
      ghostBrideScope: ghostBrideRequestScope(this.world, request),
      demonHunterScope: demonHunterRequestScope(this.world, request),
      nobleBodyScope: nobleBodyRequestScope(this.world, request),
      fragrantPairScope: fragrantPairRequestScope(this.world, request),
      animalScope: animalRequestScope(this.world, request),
      wildChildScope: wildChildRequestScope(this.world, request),
      wallScope: wallRequestScope(this.world, request),
      wallId: request.context.wall_id,
      itemInstanceId: request.context.item_instance_id,
      debateId: request.context.debate_id,
      abilityId: request.context.ability_id,
      actionWindow: request.actionWindow,
      sheriffCandidates: request.context.sheriff_candidates,
      exileCandidates: request.context.exile_candidates,
      badgeCandidates: request.context.badge_candidates,
      allowSelfDestruct:
        request.allowedTools.includes("self_destruct") ||
        request.allowedTools.includes("self_destruct_with_target"),
      duelWindow: request.context.duel_window,
      allowKnightDuel:
        request.context.stage === request.context.duel_window &&
        request.allowedTools.includes("duel"),
      deathActionId: deathTool ? request.context.death_action_id : undefined,
    });
    if (!checked.ok || !checked.sanitizedCall) {
      return toolFailure(
        this.world.locale,
        checked.error ?? "invalid_tool_arguments",
        checked.message,
      );
    }
    const evaluation = evaluateTurnConstraints(
      { validActions: [checked.sanitizedCall] },
      resolveTurnConstraints(request),
      this.world.locale,
    );
    if (!evaluation.ok) {
      return { ...fail("turn_constraints_not_satisfied"), details: evaluation.errors };
    }
    // 已接受的是脱离的候选，不是领域 commit；库存、租约完成和实际效果仍要在原 owner 重验。
    return { ok: true, action: structuredClone(checked.sanitizedCall) };
  }
}

/**
 * 负责请求对象上的交付检查、完成回调和期限别名传播。输入为机制已经绑定的原请求、
 * 当前性查询及不透明完成身份；输出为同步交付检查、一次性结算通知和有序别名绑定。
 * 元数据仅存运行时弱表，不进入模型上下文或归档。机制仍拥有权限、最早期限及单调撤权；
 * 本模块只调用已注册的规则，不以缺少交付检查或相同 JSON 字段判定请求已获授权。
 * 本模块仅写入交付弱表，不修改生命、库存或阶段；结算先删除待通知项再调用回调，异常不恢复。
 * 别名传播遇异常即停止，已完成的绑定不回滚。
 */
import type { ActionRequest } from "./actions";

type AliasPropagation = (original: ActionRequest, alias: ActionRequest) => void;
/** 原请求与别名各自登记元数据；completion 可指向同一机制窗口，不是可序列化许可。 */
interface DeliveryMetadata {
  /** 查询是否可交付；具体原体、生命版本与永久撤权由机制的查询实现负责。 */
  current?: () => boolean;
  /** 将一次 Provider 返回关联到后续领域提交或关闭，不把返回动作当成提交成功。 */
  completion?: object;
  /** 回调身份是键；同一回调重登记只更新顺序，具体别名绑定仍由该机制执行。 */
  aliases?: Map<AliasPropagation, number>;
}

/** 弱表按对象身份关联：复制请求字段不会复制当前性检查或完成身份。 */
const guards = new WeakMap<object, DeliveryMetadata>();
/** 同一完成身份同时最多保留一个待结算回调；原请求和合法别名可共享该身份。 */
const settlements = new WeakMap<object, (accepted: boolean) => void>();
/** 机制成功绑定后登记一次交付检查；保留此前已登记的别名路由。 */
export function bindRequestDeliveryGuard(
  request: object,
  isCurrent: () => boolean,
  completion?: object,
): void {
  const existing = guards.get(request);
  if (existing && "current" in existing)
    throw new Error("action_request_delivery_guard_already_bound");
  guards.set(request, { ...existing, current: isCurrent, completion });
}
/** 无登记时不额外拒绝；有检查时必须严格返回 true，不能用真值替代机制确认。 */
export function assertRequestDelivery(request: ActionRequest): void {
  const guard = guards.get(request);
  if (guard && "current" in guard && guard.current!() !== true)
    throw new Error("action_request_delivery_authority_revoked");
}
/** 登记事务请求的延后通知；无完成身份则返回 false，由调用方执行原有即时通知政策。 */
export function deferRequestDelivery(
  request: ActionRequest,
  settle: (accepted: boolean) => void,
): boolean {
  const completion = guards.get(request)?.completion;
  if (!completion) return false;
  if (settlements.has(completion)) throw new Error("action_request_delivery_already_pending");
  settlements.set(completion, settle);
  return true;
}
export function settleRequestDelivery(completion: object, accepted: boolean): void {
  const settle = settlements.get(completion);
  if (!settle) return;
  // 先消费再通知：重入或回调抛错都不会再次发送同一成功／拒绝通知，也不回滚领域前缀。
  settlements.delete(completion);
  settle(accepted);
}

/** 仅登记已成功绑定的路由；登记自身不会执行回调、校验权限或设置期限。 */
export function registerRequestAliasPropagation(
  request: object,
  order: number,
  inherit: AliasPropagation,
): void {
  let metadata = guards.get(request);
  if (!metadata) {
    metadata = {};
    guards.set(request, metadata);
  }
  (metadata.aliases ??= new Map()).set(inherit, order);
}

/** 机制自行接纳并绑定别名；按顺序调用不等于授予新行动权限。 */
export function inheritRequestAlias(original: ActionRequest, alias: ActionRequest): void {
  const routes = guards.get(original)?.aliases;
  if (!routes) return;
  // 先取路由快照再稳定排序；回调期间增删路由不改变本次名单，抛错时后续路由不执行。
  for (const [inherit] of [...routes].sort((left, right) => left[1] - right[1]))
    inherit(original, alias);
}

/** 调用方先计算最早期限；这里保留原字段展开顺序，再由已登记机制绑定新对象。 */
export function deriveBoundedRequest(original: ActionRequest, deadlineAtMs: number): ActionRequest {
  const alias = { ...original, deadlineAtMs };
  inheritRequestAlias(original, alias);
  return alias;
}

/**
 * 负责四种原有序协议及动态窗口协议的请求绑定与有限运行租约。输入为原请求、机制晚查询和期限别名；
 * 输出为同一 scope 引用和一次完成通知，只写本实例的请求／租约元数据，不写 World、生命或库存。
 * 各实例保独立表及稳定传播回调；同请求可多绑定，但真实窗口只打开对应一个交付 turn。
 * 原 envelope 或领域当前性观察失配永久关闭共同许可；别名自己的字段失配只退役该别名。
 * 合法期限别名共享最早绝对预算，观察到期后时钟回退也不复活。字段 pin 只保顶层原值引用，
 * 不深复制／冻结提示或 feed，不把相同 JSON、readonly 或请求字段当成领域许可。
 * Provider 返回不是付款；窗口完整付款后才 complete，状态先落再通知，晚异常不能二次结算。
 */
import type { ActionRequest } from "./actions";
import { bindRequestDeliveryGuard, registerRequestAliasPropagation, settleRequestDelivery } from "./request_delivery";

/** 仅晚读原 scope 字段／活跃表；不接受整个请求回调，字段接纳与读取次序在本 owner 中实现。 */
export interface RequestLeaseScopeQueries<Owner, Scope> {
  active(owner: Owner): Scope | undefined;
  owner(scope: Scope): Owner;
  actorId(scope: Scope): number;
  phase(): ActionRequest["phase"];
  stage(scope: Scope): ActionRequest["context"]["stage"];
}

/** 动态窗口只给出捕获值和晚领域查询；scope 是每个原请求独立的不透明对象，不由请求重建。
 * 日次／阶段不固定为首夜，明确声明的 context 字段只 pin 原值引用，不创建 World 或死亡许可。
 */
export interface RequestLeaseWindowQueries<Scope extends object> {
  actorId(scope: Scope): number;
  phase(scope: Scope): ActionRequest["phase"];
  day(scope: Scope): number;
  stage(scope: Scope): ActionRequest["context"]["stage"];
  current(scope: Scope): boolean;
}

/** current 仍调用原机制规则；不能据请求字段相同代替原体、生命和库存复验。 */
export interface RequestLeaseCurrentQueries<Owner, Scope> extends RequestLeaseScopeQueries<Owner, Scope> {
  current(scope: Scope): boolean;
}

/** 墙入口先查原作者；原 token／实例值在条件和记录构造位置各自读取，不缓存授权或复制作者。 */
export interface RequestLeaseItemQueries<Owner, Scope, Author> {
  active(owner: Owner): Scope | undefined;
  authors(scope: Scope): Pick<ReadonlyMap<number, Author>, "get">;
  token(scope: Scope): string;
  instanceId(author: Author): string;
  phase(): ActionRequest["phase"];
  stage(): ActionRequest["context"]["stage"];
  current(owner: Owner, scope: Scope, author: Author): boolean;
}

/** context 保原引用，记录不是请求 DTO；合法别名共享同一记录，不做深只读或序列化。 */
interface ScopeBinding<Scope> {
  scope: Scope;
  context: ActionRequest["context"];
}
/** context 身份和声明字段由本 owner 捕获；只保存值／引用，不序列化或深冻结整个 context。 */
interface WindowBinding<Scope> extends ScopeBinding<Scope> {
  fields: Array<{ key: string; value: unknown }>;
}
interface CurrentBinding<Scope> {
  binding: Scope;
  context: ActionRequest["context"];
}
/** 捕获墙的原 owner／作者编号与实例值；后续查询仍晚查活跃墙，不能由编号自行生成许可。 */
interface ItemBinding<Owner, Scope, Author> extends ScopeBinding<Scope> {
  author: Author;
  world: Owner;
  actorId: number;
  instanceId: string;
}

// 字段比较仍排除 deadlineAtMs；其有限未来／只能缩短的政策在比较成功后单独处理。
function sameIndexedFields(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return !(
    keys.length !== other.length ||
    keys.some((k) => !other.includes(k) || (source as any)[k] !== (target as any)[k])
  );
}
function everyIndexedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  );
}
function everyReflectedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  );
}

/** 窗口私有的运行完成端口；不持 World/付款回调，不可由 JSON 或请求字段重建。 */
export interface RequestLeaseTurn {
  current(): boolean;
  complete(): void;
  close(): void;
}
/** pin 只核顶层枚举字段及原值引用；嵌套数据/合法 getter/Proxy 不套新 schema 或深只读政策。 */
interface FieldPin { keys: string[]; values: unknown[] }
interface LeaseTurn<Owner, Binding> {
  owner: Owner;
  original: ActionRequest;
  binding: Binding;
  pin?: FieldPin;
  originalDeadline?: unknown;
  deadline: number | null;
  closed: boolean;
  settled: boolean;
  opened: boolean;
  completion: object;
  aliases: Set<ActionRequest>;
  handle?: RequestLeaseTurn;
}
interface LeaseEntry<Owner, Binding> {
  turn: LeaseTurn<Owner, Binding>;
  retired: boolean;
  deadline: unknown;
}
function pinFields(request: ActionRequest): FieldPin {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return { keys, values: keys.map((key) => Reflect.get(request, key)) };
}
function samePinnedFields(request: ActionRequest, pin: FieldPin): boolean {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return keys.length === pin.keys.length && keys.every((key) => {
    const index = pin.keys.indexOf(key);
    return index !== -1 && Object.is(Reflect.get(request, key), pin.values[index]);
  });
}

/**
 * 每实例唯一持有请求登记；类型入口开放明确协议，实际机制接线不传完整 request callback。
 * 私有构造签名限制 typed 调用，不是运行时权限屏障；接纳算法在本 owner 内完整执行。
 * 四个旧协议保原字段短路；动态窗口显式增加字段／日次查询，外围复用 F02 政策，不建立 Role 分派或第二租约。
 */
export class RequestLease<Owner, Scope, Binding> {
  private readonly records = new WeakMap<ActionRequest, LeaseEntry<Owner, Binding>>();
  private readonly propagate = (source: ActionRequest, target: ActionRequest): void => {
    this.inherit(source, target);
  };

  private constructor(
    private readonly order: number,
    private readonly bindRequest: (owner: Owner, request: ActionRequest, lease: RequestLease<Owner, Scope, Binding>) => void,
    private readonly matches: (owner: Owner, request: ActionRequest, binding: Binding) => boolean,
    private readonly bindingOwner: (binding: Binding) => Owner,
    private readonly bindingScope: (binding: Binding) => Scope,
    private readonly sameFields: (source: ActionRequest, target: ActionRequest) => boolean,
    private readonly domainCurrent: (owner: Owner, binding: Binding) => boolean,
  ) {}

  /**
   * 动态窗口按 actor→phase→context 身份→day→stage→声明字段核验，末位才调用领域 current。
   * bind 在条件通过后先登记关闭记录，再捕获声明字段和顶层 pin；getter 抛错保该记录关闭，不能重新 bind 复活。
   * contextKeys 的列表副本属于本实例；它不校验深层提示、JSON 或字段类型，也不把这些字段当真实许可。
   */
  static window<Scope extends object>(
    queries: RequestLeaseWindowQueries<Scope>,
    order: number,
    contextKeys: readonly string[] = [],
  ): RequestLease<Scope, Scope, WindowBinding<Scope>> {
    const keys = [...contextKeys];
    return new RequestLease<Scope, Scope, WindowBinding<Scope>>(
      order,
      (scope, request, lease) => {
        if (
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase(scope) &&
          request.context.day === queries.day(scope) &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(scope, request, { scope, context: request.context, fields: [] }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          const binding = lease.records.get(request)!.turn.binding;
          for (const key of keys) binding.fields.push({ key, value: Reflect.get(binding.context, key) });
          lease.capture(request);
        }
      },
      (scope, request, binding) =>
        request.actorId === queries.actorId(scope) &&
        request.phase === queries.phase(scope) &&
        request.context === binding.context &&
        request.context.day === queries.day(scope) &&
        request.context.stage === queries.stage(scope) &&
        binding.fields.every(({ key, value }) => Object.is(Reflect.get(request.context, key), value)),
      (binding) => binding.scope,
      (binding) => binding.scope,
      sameIndexedFields,
      (_scope, binding) => queries.current(binding.scope),
    );
  }

  /** actor→phase→day→stage；查询还先核同一活跃 scope，末位晚核机制当前性。 */
  static actorPhaseDayStage<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, ScopeBinding<Scope>> {
    return new RequestLease<Owner, Scope, ScopeBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const scope = queries.active(owner);
        if (
          scope &&
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(owner, request, { scope, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, binding) =>
        queries.owner(binding.scope) === owner &&
        queries.active(owner) === binding.scope &&
        request.actorId === queries.actorId(binding.scope) &&
        request.context === binding.context &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(binding.scope),
      (binding) => queries.owner(binding.scope),
      (binding) => binding.scope,
      sameIndexedFields,
      (_owner, binding) => queries.current(binding.scope),
    );
  }

  /** stage→phase→day→actor→current；查询保原 context→stage→day→phase→current 顺序和 Reflect.get 比较。 */
  static stagePhaseDayActor<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.context.stage === queries.stage(b) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.actorId === queries.actorId(b) &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        request.phase === queries.phase() &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyReflectedField,
      () => true, // 原 matches 已在末位调用本族 current，不重复那一次。
    );
  }

  /** actor→phase→stage→day→current；查询的 phase 必须先于 context 身份，不重排成上一种协议。 */
  static actorPhaseStageDay<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.actorId === queries.actorId(b) &&
          request.phase === queries.phase() &&
          request.context.stage === queries.stage(b) &&
          request.context.day === 1 &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.phase === queries.phase() &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyIndexedField,
      () => true,
    );
  }

  /** 原物品入口只核 token/instance；phase/day/stage 留在查询，原作者当前性在查询成功后才晚核。 */
  static item<Owner, Scope, Author>(
    queries: RequestLeaseItemQueries<Owner, Scope, Author>,
    order: number,
  ): RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>> {
    return new RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>>(
      order,
      (world, request, lease) => {
        const a = queries.active(world),
          author = a == null ? undefined : queries.authors(a).get(request.actorId);
        if (
          a &&
          author &&
          request.context.wall_id === queries.token(a) &&
          request.context.item_instance_id === queries.instanceId(author)
        ) {
          lease.records.set(request, lease.entry(world, request, {
            scope: a,
            world,
            actorId: request.actorId,
            instanceId: queries.instanceId(author),
            context: request.context,
            author,
          }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (world, request, binding) =>
        queries.active(world) === binding.scope &&
        request.actorId === binding.actorId &&
        request.context === binding.context &&
        request.context.wall_id === queries.token(binding.scope) &&
        request.context.item_instance_id === binding.instanceId &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(),
      (binding) => binding.world,
      (binding) => binding.scope,
      sameIndexedFields,
      (owner, binding) => queries.current(owner, binding.scope, binding.author),
    );
  }

  /** 条件与 set callee 保原位置；同对象已登记后不得重新 bind 来复活旧 turn。 */
  bind(owner: Owner, request: ActionRequest): void {
    if (this.records.has(request)) return;
    this.bindRequest(owner, request, this);
  }

  /** 只分配运行记录；原 binding/context 已在参数原位置读出。pin 在 set 与传播登记之后才读取。 */
  private entry(owner: Owner, original: ActionRequest, binding: Binding): LeaseEntry<Owner, Binding> {
    return { turn: { owner, original, binding, closed: true, settled: false, opened: false,
      completion: {}, aliases: new Set(), deadline: null }, retired: false, deadline: undefined };
  }

  private capture(request: ActionRequest): void {
    const entry = this.records.get(request)!, turn = entry.turn;
    // 捕获期间先保持关闭：新增 keys/getter 抛错保原已写记录／传播前缀，恢复字段也不重开。
    turn.pin = pinFields(request);
    entry.deadline = request.deadlineAtMs;
    turn.originalDeadline = entry.deadline;
    if (entry.deadline === undefined) turn.closed = false;
    else if (typeof entry.deadline === "number" && Number.isFinite(entry.deadline) && entry.deadline > Date.now()) {
      turn.deadline = entry.deadline;
      turn.closed = false;
    }
  }

  /** 外来 World／未登记请求先拒；alias 自身失配先隔离，不读取或毒化 original。 */
  scope(owner: Owner, request: ActionRequest): Scope | undefined {
    const entry = this.records.get(request);
    if (!entry || entry.turn.owner !== owner || entry.turn.closed || entry.retired) return;
    const turn = entry.turn;
    if (request !== turn.original) {
      try {
        if (!samePinnedFields(request, turn.pin!) || !Object.is(request.deadlineAtMs, entry.deadline)) {
          entry.retired = true;
          return;
        }
      } catch (error) {
        entry.retired = true;
        throw error;
      }
    }
    try {
      // 各协议仍按其声明的 ordered matches 查询 original；共同 context.stage 变坏会关共同 turn。
      if (!this.matches(owner, turn.original, turn.binding) ||
          !samePinnedFields(turn.original, turn.pin!) ||
          !Object.is(turn.original.deadlineAtMs, turn.originalDeadline) ||
          !this.domainCurrent(owner, turn.binding) ||
          (turn.deadline !== null && turn.deadline <= Date.now())) {
        turn.closed = true;
        return;
      }
      return this.bindingScope(turn.binding);
    } catch (error) {
      turn.closed = true;
      throw error;
    }
  }

  /**
   * 真正窗口在 create 后打开交付：各绑定实例不争写 guard。前后登记的 alias 同 guard／completion，
   * 这些引用只留本 owner 的运行集合，不挂 context。每个 Wall request 的 turn 独立于整个墙。
   */
  openDelivery(owner: Owner, request: ActionRequest): RequestLeaseTurn | undefined {
    if (!this.scope(owner, request)) return;
    const turn = this.records.get(request)!.turn;
    if (!turn.handle) turn.handle = {
      current: () => this.scope(owner, request) !== undefined,
      complete: () => this.finish(turn, true),
      close: () => this.finish(turn, false),
    };
    if (!turn.opened) {
      bindRequestDeliveryGuard(turn.original, () => this.scope(owner, turn.original) !== undefined, turn.completion);
      turn.opened = true;
      for (const alias of turn.aliases) this.bindDelivery(turn, alias);
    }
    return turn.handle;
  }

  private bindDelivery(turn: LeaseTurn<Owner, Binding>, request: ActionRequest): void {
    bindRequestDeliveryGuard(request, () => this.scope(turn.owner, request) !== undefined, turn.completion);
  }

  /** 付款结果只由真实窗口给出；不重查已被付款改变的 pending scope。先落终态再发一次通知。 */
  private finish(turn: LeaseTurn<Owner, Binding>, accepted: boolean): void {
    if (turn.settled) return;
    turn.closed = true;
    turn.settled = true;
    turn.aliases.clear();
    settleRequestDelivery(turn.completion, accepted);
  }

  /** 先核来源，再原 ordered fields，最后有限未来期限；坏目标／其 getter 异常不修改来源预算。 */
  private inherit(source: ActionRequest, target: ActionRequest): void {
    const sourceEntry = this.records.get(source);
    if (!sourceEntry || !this.scope(sourceEntry.turn.owner, source) || this.records.has(target)) return;
    if (!this.sameFields(source, target)) return;
    const turn = sourceEntry.turn;
    // 原 === 比较通过后仍须核 F02 pin（含 +0/-0 及晚 getter 原值）；非法目标不得先写记录／缩预算。
    if (!samePinnedFields(target, turn.pin!)) return;
    const deadline = target.deadlineAtMs;
    if (typeof deadline !== "number" || !Number.isFinite(deadline) || deadline <= Date.now() ||
        (turn.deadline !== null && deadline > turn.deadline)) return;
    this.records.set(target, { turn, retired: false, deadline });
    turn.deadline = deadline;
    turn.aliases.add(target);
    registerRequestAliasPropagation(target, this.order, this.propagate);
    if (turn.opened) this.bindDelivery(turn, target);
  }
}

/**
 * 负责猎魔人原参与者的私态引用证据、最近同步审计数据及 checkpoint 数据编码。
 * 输入保留原 Participant／checkpoint 字段与已捕获库存；输出为原引用检查、原副本或原异常。
 * 数据仍放在同一参与者对象，不建第二库存或缓存；JSON 影子只描述最近同步提交，不授予行动。
 * World、生命、夜间、资源资格、请求与冻结仍由 authority 在原点复验；委托查询只在原分支晚调用。
 * 编码、字段写入或成功标记失败保留此前前缀，不退款、刷新 live 数据或加强原 schema 接受面。
 */
import { types } from "node:util";
import { Camp } from "../../../../core/domain/identity";
import type { Role } from "../../../../core/domain/identity";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { VictoryComponent } from "../../../../core/domain/components/victory";
import type { VotingRightComponent } from "../../../../core/domain/components/voting_right";
import type { StatusMark } from "@ai-werewolf-arena/game-contract";
import type { StatusMarkSnapshot } from "../../../../core/domain/components/status_marks";
import { demonJson, demonSnapshot, ownDemonData } from "./state-slot";

/** 顶层槽引用与嵌套库存路径分别保留原身份；JSON 相等不能恢复被替换的原引用。 */
export interface DemonParticipantStateData {
  privateState: RoleComponent["privateState"];
  privateRefs: ReadonlyArray<readonly [string, unknown]>;
  inventoryRefs: ReadonlyArray<readonly [readonly string[], object]>;
  victoryJson: string;
  auditPrivateJson: string;
  delegatedKey: "noble" | "secretBody" | null;
}
/** 两串仍存在原 checkpoint 中，物理警徽／票权提交及其权限属于原同步领域流程。 */
export interface DemonCheckpointAuditData {
  badge: object;
  vote: object;
  badgeJson: string;
  voteJson: string;
}
export interface DemonDelegatedPrivateData {
  nobleId: number;
  bodyId: number;
  noble: unknown;
  body: unknown;
}
type PrivateData = Pick<DemonParticipantStateData, "privateState" | "inventoryRefs" | "privateRefs" | "auditPrivateJson" | "delegatedKey">;
type AuditData = Pick<DemonParticipantStateData, "privateState" | "auditPrivateJson">;

/** 原 descriptor 递归先记录父路径再访问子对象；不新增 seen/schema，原捕获方已按原序验证数据。 */
export function inventoryReferences(value: object): Array<readonly [readonly string[], object]> {
  const references: Array<readonly [readonly string[], object]> = [];
  const visit = (item: object, path: string[]): void => {
    for (const [key, descriptor] of Object.entries(Object.getOwnPropertyDescriptors(item))) {
      if ("value" in descriptor && descriptor.value && typeof descriptor.value === "object") {
        const next = [...path, key];
        references.push([next, descriptor.value]);
        visit(descriptor.value, next);
      }
    }
  };
  visit(value, []);
  return references;
}
export function originalInventory(p: Pick<PrivateData, "privateState" | "inventoryRefs">): boolean {
  return p.inventoryRefs.every(([path, original]) => {
    let current: unknown = p.privateState;
    for (const key of path) current = ownDemonData(current, key);
    return current === original && !types.isProxy(original);
  });
}
/** 可选 handoffPolicy 的缺失与 accessor 拒绝仍有区别；原 own-data 和数值接受集合保持。 */
export function demonBadgeJson(badge: unknown): string | null {
  if (!badge || typeof badge !== "object" || types.isProxy(badge)) return null;
  const optional = Object.getOwnPropertyDescriptor(badge, "handoffPolicy");
  if (optional && !("value" in optional)) return null;
  const isSheriff = ownDemonData(badge, "isSheriff"),
    destroyed = ownDemonData(badge, "destroyed"),
    voteWeight = ownDemonData(badge, "voteWeight"),
    handoffPolicy = ownDemonData(badge, "handoffPolicy");
  return typeof isSheriff === "boolean" &&
    typeof destroyed === "boolean" &&
    typeof voteWeight === "number" &&
    Number.isFinite(voteWeight) &&
    voteWeight > 0 &&
    (handoffPolicy === undefined ||
      handoffPolicy === "awa_next_seat_v1" ||
      handoffPolicy === "awa_holder_choice_v1")
    ? JSON.stringify({
        isSheriff,
        destroyed,
        voteWeight,
        ...(handoffPolicy === undefined ? {} : { handoffPolicy }),
      })
    : null;
}
export function demonVoteJson(vote: unknown): string | null {
  const weight = ownDemonData(vote, "weight"),
    canVote = ownDemonData(vote, "canVote");
  return typeof weight === "number" &&
    Number.isFinite(weight) &&
    (weight > 0 || (weight === 0 && canVote === false)) &&
    typeof canVote === "boolean"
    ? JSON.stringify({ weight, canVote })
    : null;
}
/** 私态先安全编码；无委托即比较原串，有委托才复验并逐次 parse／删键／stringify。 */
export function privateAuditCurrent(p: PrivateData, delegatedCurrent: () => boolean): boolean {
  const current = demonJson(p.privateState);
  if (!current) return false;
  if (!p.delegatedKey) return current === p.auditPrivateJson;
  if (!delegatedCurrent()) return false;
  const actual = JSON.parse(current),
    expected = JSON.parse(p.auditPrivateJson);
  delete actual[p.delegatedKey];
  delete expected[p.delegatedKey];
  return JSON.stringify(actual) === JSON.stringify(expected);
}
export function committedPrivate(p: PrivateData & { readonly id: number }, readDelegated: () => DemonDelegatedPrivateData): Record<string, unknown> {
  const cached = JSON.parse(p.auditPrivateJson) as Record<string, unknown>;
  if (p.delegatedKey) {
    const owned = readDelegated();
    if (p.id !== (p.delegatedKey === "noble" ? owned.nobleId : owned.bodyId))
      throw Error("demon_hunter_delegated_actor_invalid");
    cached[p.delegatedKey] = p.delegatedKey === "noble" ? owned.noble : owned.body;
  }
  return cached;
}
/** 原验证与 delegatedKey 选择已经完成；原位置捕获同一容器和路径，不克隆 live 库存。 */
export function captureDemonParticipantPrivateData(
  privateState: object,
  delegatedKey: DemonParticipantStateData["delegatedKey"],
  privateJson: string,
): Omit<DemonParticipantStateData, "victoryJson"> {
  return {
    privateState: privateState as RoleComponent["privateState"],
    privateRefs: Object.entries(privateState),
    inventoryRefs: inventoryReferences(privateState).filter(
      ([path]) => path.length === 1 || path[0] !== delegatedKey,
    ),
    delegatedKey,
    auditPrivateJson: privateJson,
  };
}
/** 原身份前置检查通过后才比较顶层 descriptor；不与先前 World／Camp 查询合并或提前。 */
export function demonPrivateRefsCurrent(p: Pick<PrivateData, "privateRefs">, descriptors: PropertyDescriptorMap): boolean {
  return Object.keys(descriptors).length === p.privateRefs.length &&
    p.privateRefs.every(
      ([key, value]) =>
        descriptors[key] && "value" in descriptors[key]! && descriptors[key]!.value === value,
    );
}
/** 调用方已核原消耗／history 或 frame current；原 JSON 求值后才覆盖最近安全串。 */
export function refreshDemonParticipantAudit(p: AuditData): void {
  p.auditPrivateJson = demonJson(p.privateState)!;
}
/** 原药 frame 资格已经复验，按原顺序复制完整私态并读取原生药四层数据；不重算库存。 */
export function captureDemonWitchAuditData(p: AuditData) {
  const original = demonSnapshot(p.privateState) as Record<string, unknown>,
    abilities = ownDemonData(original, "abilities") as Record<string, unknown>,
    snapshot = ownDemonData(abilities, "native:potion") as Record<string, unknown>,
    state = ownDemonData(snapshot, "state") as Record<string, unknown>;
  return { original, abilities, snapshot, state };
}
/** 已置 witchOpened 后进行原同步 reset：先编码模板，再写三个 live 字段、核整容器，最后更新 audit。 */
export function resetDemonWitchParticipantData(
  p: AuditData, original: Record<string, unknown>, abilities: Record<string, unknown>,
  snapshot: Record<string, unknown>, state: Record<string, unknown>, originalState: Record<string, unknown>,
) {
  const resetState: Record<string, unknown> = {
    ...state,
    healUsedThisNight: false,
    poisonUsedThisNight: false,
    canSelfHeal: false,
  };
  const resetAbility = { ...snapshot, state: resetState };
  const resetJson = JSON.stringify(resetAbility);
  originalState.healUsedThisNight = false;
  originalState.poisonUsedThisNight = false;
  originalState.canSelfHeal = false;
  const resetPrivate = { ...original, abilities: { ...abilities, "native:potion": resetAbility } };
  if (demonJson(p.privateState) !== JSON.stringify(resetPrivate))
    throw new Error("demon_hunter_native_reset_failed");
  p.auditPrivateJson = JSON.stringify(resetPrivate);
  return { resetState, resetAbility, resetJson };
}
/** 原调用方已核 potion/current；先编码／比较完整期望私态，再原成功标记，最后写 audit。 */
export function commitDemonWitchParticipantData(
  p: AuditData, original: Record<string, unknown>, abilities: Record<string, unknown>,
  snapshot: Record<string, unknown>, resetState: Record<string, unknown>, resetAbility: Record<string, unknown>,
  n: { readonly day: number }, potion: "heal" | "poison" | "none", markCommitted: (json: string) => void,
): boolean {
  const expectedState = { ...resetState };
  if (potion !== "none") {
    if ((resetState[potion] as number) < 1) return false;
    expectedState[potion] = (resetState[potion] as number) - 1;
    expectedState[potion === "heal" ? "healUsedThisNight" : "poisonUsedThisNight"] = true;
  }
  const expectedAbility = {
    ...resetAbility,
    state: expectedState,
    uses: (snapshot.uses as number) + (potion === "none" ? 0 : 1),
    lastUsedDay: n.day,
  };
  const expectedPrivate = {
    ...original,
    abilities: { ...abilities, "native:potion": expectedAbility },
  };
  const json = JSON.stringify(expectedPrivate);
  if (demonJson(p.privateState) !== json) return false;
  markCommitted(json);
  p.auditPrivateJson = json;
  return true;
}
/** 原 native kind/id 已选；保原 optional 参与者串、条件 parse 与后续三层读取。 */
export function captureDemonNativeAuditData(p: AuditData | undefined, id: string) {
  const originalJson = p?.auditPrivateJson;
  const original = originalJson ? (JSON.parse(originalJson) as Record<string, unknown>) : null;
  const abilities = original?.abilities as Record<string, unknown> | undefined;
  const snapshot = abilities?.[id] as Record<string, unknown> | undefined;
  const state = snapshot?.state as Record<string, unknown> | undefined;
  return { originalJson, original, abilities, snapshot, state };
}
/**
 * 资格及目标复验留在调用点。Seer 依原捕获阵营准备行，写历史后才写 uses／lastUsedDay；Guard 保原重复规则。
 * 只有整私态编码核对成功后才调用原 committed 标记，再写 audit；晚 JSON／字段错误不撤销前写。
 * nativeArrayPush 必须是 authority 原模块位置捕获的函数，不在新模块初始化时重捕获。
 */
export function commitDemonNativeParticipantData(
  p: AuditData, original: Record<string, unknown> | null, abilities: Record<string, unknown> | undefined,
  snapshot: Record<string, unknown>, state: Record<string, unknown>, originalState: object,
  ability: object, kind: "seer_check" | "guard", id: string, day: number,
  targetId: number | null, inspection: unknown, readCamp: (id: number) => Camp,
  nativeArrayPush: typeof Array.prototype.push, markCommitted: () => void,
): boolean {
  let nextState: Record<string, unknown>;
  if (kind === "seer_check") {
    if (targetId === null) return false;
    const result = { kind: "camp", camp: readCamp(targetId) };
    if (demonJson(inspection) !== demonJson(result)) return false;
    const row = { targetId, isWerewolf: result.camp === Camp.Wolf, result: { ...result } };
    nextState = {
      ...state,
      lastTarget: targetId,
      lastIsWerewolf: row.isWerewolf,
      lastResult: { ...result },
      history: [...(state.history as unknown[]), row],
    };
    const liveState = originalState as Record<string, unknown>;
    liveState.lastTarget = targetId;
    liveState.lastIsWerewolf = row.isWerewolf;
    liveState.lastResult = { ...result };
    nativeArrayPush.call(ownDemonData(originalState, "history"), row);
  } else {
    if (targetId !== null && snapshot.lastUsedDay === day - 1 && state.lastTarget === targetId)
      return false;
    nextState = { ...state, lastTarget: targetId };
    (originalState as Record<string, unknown>).lastTarget = targetId;
  }
  const nextAbility = {
    ...snapshot,
    state: nextState,
    uses: (snapshot.uses as number) + (targetId === null ? 0 : 1),
    lastUsedDay: day,
  };
  (ability as Record<string, unknown>).uses = nextAbility.uses;
  (ability as Record<string, unknown>).lastUsedDay = day;
  const json = JSON.stringify({ ...original, abilities: { ...abilities, [id]: nextAbility } });
  if (demonJson(p.privateState) !== json)
    throw new Error("demon_hunter_native_night_commit_failed");
  markCommitted();
  p.auditPrivateJson = json;
  return true;
}
export function captureDemonHunterAuditData(p: AuditData) {
  const originalJson = p.auditPrivateJson,
    original = JSON.parse(originalJson),
    hunter = original.hunter;
  return { originalJson, original, hunter };
}
/** 原死亡枪资格已复验；真实 canShoot 写后编码，失败保已耗库存及旧审计串。 */
export function consumeDemonHunterParticipantData(
  p: AuditData, state: object, original: Record<string, unknown>, hunter: Record<string, unknown>,
  markCommitted: () => void,
): void {
  (state as Record<string, unknown>).canShoot = false;
  const json = JSON.stringify({ ...original, hunter: { ...hunter, canShoot: false } });
  if (demonJson(p.privateState) !== json)
    throw new Error("demon_hunter_native_hunter_commit_failed");
  markCommitted();
  p.auditPrivateJson = json;
}
/** 原 complete／metadata检查已执行；各字段逐次解码，生命与委托读取只在原属性位置调用。 */
export function projectDemonParticipantCheckpoint(
  p: DemonParticipantStateData & { readonly id: number; readonly kind: Role; readonly camp: Camp },
  cp: DemonCheckpointAuditData & { readonly seat: number; readonly name: string },
  marks: ReadonlyArray<readonly [StatusMark, StatusMarkSnapshot | null]>,
  readAlive: () => boolean, readDelegated: () => DemonDelegatedPrivateData,
) {
  return {
    id: p.id,
    seat: cp.seat,
    name: cp.name,
    role: p.kind,
    camp: p.camp,
    alive: readAlive(),
    privateState: committedPrivate(p, readDelegated),
    victory: { affiliations: JSON.parse(p.victoryJson) as VictoryComponent["affiliations"] },
    vote: JSON.parse(cp.voteJson) as { weight: number; canVote: boolean },
    badge: JSON.parse(cp.badgeJson) as {
      isSheriff: boolean;
      destroyed: boolean;
      voteWeight: number;
      handoffPolicy?: import("../../../../core/domain/board").SheriffBadgePolicy;
    },
    marks: marks.flatMap(([mark, snapshot]) => (snapshot?.present ? [mark] : [])),
  };
}
/** 真实警徽批次已通过核验并标记 committed；依原 map 顺序逐个先写 badge 串、再 vote 串。 */
export function acceptDemonBadgeAudits(
  before: ReadonlyMap<number, { readonly cp: DemonCheckpointAuditData }>,
  expected: ReadonlyMap<number, { readonly badge: object; readonly vote: object }>,
): void {
  for (const [id, next] of expected) {
    const cp = before.get(id)!.cp;
    cp.badgeJson = JSON.stringify(next.badge);
    cp.voteJson = JSON.stringify(next.vote);
  }
}
/** RedMoon 族的三字段写已发生；整容器核对失败仍保前写，不重做族 schema 或退款。 */
export function acceptDemonRedMoonAudit(p: AuditData, expected: string): void {
  if (demonJson(p.privateState) !== expected) throw new Error("red_moon_state_commit_failed");
  p.auditPrivateJson = expected;
}
/**
 * 原 badge预检完成后才准备两份期望数据；翻牌→canVote→weight 后核内容，再依原顺序更新两引用表及双审计串。
 * 失败不补写余字段、不改变生命，也不能拿最近安全串当成可重新付款的库存。
 */
export function commitDemonIdiotParticipantData(p: PrivateData, cp: DemonCheckpointAuditData): boolean {
  const next = { revealed: true };
  const original = JSON.parse(p.auditPrivateJson) as Record<string, unknown>;
  const expectedPrivate = JSON.stringify({ ...original, idiot: next });
  const expectedVote = JSON.stringify({ ...JSON.parse(cp.voteJson), canVote: false, weight: 0 });
  (p.privateState as { idiot: typeof next }).idiot = next;
  (cp.vote as VotingRightComponent).canVote = false;
  (cp.vote as VotingRightComponent).weight = 0;
  if (demonJson(p.privateState) !== expectedPrivate || demonVoteJson(cp.vote) !== expectedVote)
    throw new Error("demon_hunter_idiot_commit_failed");
  p.privateRefs = p.privateRefs.map(
    ([key, value]) => [key, key === "idiot" ? next : value] as const,
  );
  p.inventoryRefs = p.inventoryRefs.map(
    ([path, value]) => [path, path.length === 1 && path[0] === "idiot" ? next : value] as const,
  );
  p.auditPrivateJson = expectedPrivate;
  cp.voteJson = expectedVote;
  return true;
}

/**
 * 负责猎魔人完整数据槽：原 schema／工具副本、creator、同引用查询、安装及已接受历史写入。
 * 输入为原角色或 authority 的原 state／history／夜时钟；输出保持 live 引用和唯一 historyJson。
 * Node 快照只在原入口拒绝外来 descriptor／Proxy，校验副本不替换运行槽；公共纯结构仍归契约包。
 * 原下一历史先编码，再 push 和更新 JSON；后续 actor 审计、夜选择、请求结算和 stock 写权仍归 authority。
 * 此 owner 不建镜像／第二 WeakMap、不冻结 live 数据或把类型／查询当许可；失败保原部分写入前缀。
 */
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import { types } from "node:util";
import type { RoleComponent } from "../../../../core";
import { DEMON_HUNTER_POLICY, readDemonHunterState as readState, readDemonHuntTool as readTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
import type { DemonHunterState, DemonHuntTool } from "@ai-werewolf-arena/game-contract/facts/demon-hunter";
export { DEMON_HUNTER_POLICY };
export const DEMON_HUNTER_ROLE = "demon_hunter" as const;
export function ownDemonData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  return descriptor && "value" in descriptor ? descriptor.value : undefined;
}
export function demonSnapshot(
  value: unknown,
  seen = new Set<object>(),
  depth = 0,
  arrayLimit = 256,
): unknown {
  return snapshotPlainData(value, seen, depth, arrayLimit, "demon_hunter_data_invalid");
}
export function demonJson(value: unknown): string | null {
  try {
    return JSON.stringify(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function exactDemonData(
  value: unknown,
  keys: readonly string[],
): value is Record<string, unknown> {
  return (
    !!value &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.keys(value).length === keys.length &&
    keys.every((key) => Object.hasOwn(value, key))
  );
}
export function freshDemonHunterState(): DemonHunterState {
  return { policy: DEMON_HUNTER_POLICY, history: [] };
}
export function readDemonHunterState(value: unknown): DemonHunterState | null {
  try {
    return readState(demonSnapshot(value));
  } catch {
    return null;
  }
}
export function getDemonHunterState(role: RoleComponent | undefined): DemonHunterState | undefined {
  const s = ownDemonData(ownDemonData(role, "privateState"), "demonHunter");
  // 复制只用于验证；成功后仍返回原 slot，不能让查询生成第二份 live 状态。
  return readDemonHunterState(s) ? (s as DemonHunterState) : undefined;
}
export function readDemonHuntTool(value: unknown): DemonHuntTool | null {
  try {
    return readTool(demonSnapshot(value));
  } catch {
    return null;
  }
}

/** 唯一 live state／history 和已提交 JSON 留在原 binding 对象，不复制第二份运行库存。 */
export interface DemonHunterStateSlot {
  state: DemonHunterState;
  history: DemonHunterState["history"];
  historyJson: string;
}

/** 初始化仍先求值左侧 privateState，再调用原 creator；没有 schema、授权或新冻结。 */
export function installDemonHunterStateSlot(role: RoleComponent): void {
  (role.privateState as { demonHunter: DemonHunterState }).demonHunter = freshDemonHunterState();
}

/** 原安装字段依次取 state、history，再给空历史 JSON；临时返回对象不成为第二份 live store。 */
export function captureDemonHunterStateSlot(state: DemonHunterState): DemonHunterStateSlot {
  return { state, history: state.history, historyJson: "[]" };
}

/** 数据当前性保持原历史引用优先、已校验历史 JSON 后查；原参与者与 World alias 仍由 authority 核对。 */
export function demonHunterHistoryCurrent(b: DemonHunterStateSlot, state: DemonHunterState): boolean {
  return ownDemonData(b.state, "history") === b.history && demonJson(state.history) === b.historyJson;
}

/**
 * 完整原历史写命令。各 history 与 n.day 均在原表达式处读取；不提前缓存夜时钟。
 * 下一历史 JSON 失败时尚未 push；push 后再写 historyJson，后续抛错保留原历史写入前缀。
 * 返回原冻结 choice；actor.auditPrivateJson、n.choice／turn 和请求结算必须仍由 authority 随后按原序提交。
 */
export function appendDemonHunterChoiceData(
  b: DemonHunterStateSlot,
  n: { readonly day: number },
  targetId: number | null,
): Readonly<DemonHunterState["history"][number]> | null {
  const length = Object.getOwnPropertyDescriptor(b.history, "length");
  if (!length?.writable || !Object.isExtensible(b.history) || (b.history.at(-1)?.day ?? 1) >= n.day)
    return null;
  const choice = Object.freeze({ day: n.day, targetId });
  const nextHistoryJson = demonJson([...b.history, choice]);
  if (nextHistoryJson === null) return null;
  b.history.push(choice);
  b.historyJson = nextHistoryJson;
  return choice;
}
